import os

for root, dirs, files in os.walk('.'):
    # Skip hidden dirs and the skill dir to keep output focused
    dirs[:] = [d for d in dirs if not d.startswith('.') and d != 'node_modules']
    depth = root.count(os.sep)
    if depth > 3:
        continue
    for f in files:
        print(os.path.join(root, f))

import os

for root, dirs, files in os.walk('.codex/skills/docx'):
    depth = root.count(os.sep)
    if depth > 6:
        continue
    rel = os.path.relpath(root, '.codex/skills/docx')
    print(f"[{rel}]")
    for f in sorted(files):
        print("   ", f)

